CREATE TABLE "violation_reliefs" ("id" varchar not null, "device_id" varchar, "violation_id" varchar not null, "kind" varchar not null, "amount" numeric, "decided_on" date not null, "decision_number" varchar, "decision_document_id" varchar, "reason" text not null, "recorded_by" varchar, "created_at" datetime, "updated_at" datetime, foreign key("violation_id") references "violations"("id") on delete cascade, foreign key("decision_document_id") references "archive_documents"("id") on delete set null, foreign key("recorded_by") references "users"("id") on delete set null, primary key ("id"));
CREATE INDEX "rk_violation_reliefs_decision_document_id_lookup" on "violation_reliefs" ("decision_document_id");
CREATE INDEX "violation_reliefs_violation_id_decided_on_index" on "violation_reliefs" ("violation_id", "decided_on");
CREATE TABLE "violations" ("id" varchar not null, "device_id" varchar, "individual_id" varchar not null, "title" varchar not null, "description" text, "occurred_on" date not null, "discovered_on" date, "status" varchar not null default ('alleged'), "complaint_id" varchar, "notes" text, "recorded_by" varchar, "created_at" datetime, "updated_at" datetime, "violation_category_id" varchar, "restitution_amount" numeric, "currency_id" varchar, foreign key("violation_category_id") references violation_categories("id") on delete restrict on update no action, foreign key("individual_id") references individuals("id") on delete cascade on update no action, foreign key("complaint_id") references complaints("id") on delete set null on update no action, foreign key("recorded_by") references users("id") on delete set null on update no action, foreign key("currency_id") references "currencies"("id") on delete set null, primary key ("id"));
CREATE INDEX "rk_violations_complaint_id_lookup" on "violations" ("complaint_id");
CREATE INDEX "rk_violations_currency_id_lookup" on "violations" ("currency_id");
CREATE INDEX "rk_violations_violation_category_id_lookup" on "violations" ("violation_category_id");
CREATE INDEX "violations_individual_id_occurred_on_index" on "violations" ("individual_id", "occurred_on");
CREATE INDEX "violations_occurred_on_index" on "violations" ("occurred_on");
CREATE INDEX "violations_status_occurred_on_index" on "violations" ("status", "occurred_on");
CREATE TABLE "voucher_entries" ("id" varchar not null, "voucher_id" varchar not null, "treasury_id" varchar not null, "currency_id" varchar, "amount" numeric not null, "amount_in_base" numeric, "entry_date" date not null, "created_at" datetime, "updated_at" datetime, foreign key("voucher_id") references "vouchers"("id") on delete cascade, foreign key("treasury_id") references "treasuries"("id") on delete restrict, foreign key("currency_id") references "currencies"("id") on delete restrict, primary key ("id"));
CREATE INDEX "voucher_entries_treasury_id_currency_id_index" on "voucher_entries" ("treasury_id", "currency_id");
CREATE TABLE "voucher_fundings" ("id" varchar not null, "device_id" varchar, "voucher_id" varchar not null, "income_id" varchar not null, "amount" numeric not null, "created_at" datetime, "updated_at" datetime, "income_allocation_id" varchar, foreign key("income_id") references incomes("id") on delete restrict on update no action, foreign key("voucher_id") references vouchers("id") on delete cascade on update no action, foreign key("income_allocation_id") references "income_allocations"("id") on delete set null, primary key ("id"));
CREATE UNIQUE INDEX "voucher_fundings_voucher_id_income_id_unique" on "voucher_fundings" ("voucher_id", "income_id");
CREATE TABLE "vouchers" ("id" varchar not null, "device_id" varchar, "kind" varchar not null, "status" varchar not null default ('draft'), "number" varchar, "number_year" integer, "number_sequence" integer, "voucher_date" date not null, "treasury_id" varchar not null, "to_treasury_id" varchar, "amount" numeric not null, "currency_id" varchar, "rate_to_base" numeric, "amount_in_base" numeric, "counter_amount" numeric, "counter_currency_id" varchar, "counter_rate_to_base" numeric, "counter_amount_in_base" numeric, "exchange_difference_in_base" numeric, "finance_item_id" varchar, "department_id" varchar, "archive_entity_id" varchar, "individual_id" varchar, "party_name" varchar, "payment_method" varchar not null default ('cash'), "reference" varchar, "description" text, "approver_position_id" varchar, "approved_by" varchar, "approver_name" varchar, "approver_title" varchar, "approved_at" datetime, "reverses_id" varchar, "cancelled_at" datetime, "cancel_reason" text, "created_by" varchar, "created_at" datetime, "updated_at" datetime, "income_id" varchar, "finance_channel_id" varchar, "expense_id" varchar, "advance_id" varchar, "approval_notice_to" varchar, "approval_document_id" varchar, "signed_by_label" varchar, "signed_by_individual_id" varchar, "approval_recorded_by" varchar, "archived_at" datetime, "archived_by" varchar, "archive_reason" varchar, foreign key("advance_id") references advances("id") on delete restrict on update no action, foreign key("finance_channel_id") references finance_channels("id") on delete restrict on update no action, foreign key("income_id") references incomes("id") on delete restrict on update no action, foreign key("treasury_id") references treasuries("id") on delete restrict on update no action, foreign key("to_treasury_id") references treasuries("id") on delete restrict on update no action, foreign key("currency_id") references currencies("id") on delete restrict on update no action, foreign key("counter_currency_id") references currencies("id") on delete restrict on update no action, foreign key("finance_item_id") references finance_items("id") on delete restrict on update no action, foreign key("department_id") references departments("id") on delete set null on update no action, foreign key("archive_entity_id") references archive_entities("id") on delete set null on update no action, foreign key("individual_id") references individuals("id") on delete set null on update no action, foreign key("approver_position_id") references positions("id") on delete set null on update no action, foreign key("approved_by") references users("id") on delete set null on update no action, foreign key("reverses_id") references vouchers("id") on delete restrict on update no action, foreign key("created_by") references users("id") on delete set null on update no action, foreign key("expense_id") references expenses("id") on delete restrict on update no action, foreign key("archived_by") references "users"("id") on delete set null, primary key ("id"));
CREATE INDEX "vouchers_approval_document_id_index" on "vouchers" ("approval_document_id");
CREATE INDEX "vouchers_archived_at_index" on "vouchers" ("archived_at");
CREATE INDEX "vouchers_kind_index" on "vouchers" ("kind");
CREATE UNIQUE INDEX "vouchers_number_unique" on "vouchers" ("number");
CREATE INDEX "vouchers_status_voucher_date_index" on "vouchers" ("status", "voucher_date");
